EDG=[("A","B"),("B","C"),("A","A′"),("B","B′"),("C","C′"),("A′","B′"),("B′","C′"),("C′","D′"),("D′","A′")]
HID=[("A","D"),("D","C"),("D","D′")]
def seg(a,b,c="#1d2a6b",w=3,dash=0,t="",dx=0,dy=0):
  g={"p":[*P[a],*P[b]],"c":c,"w":w}
  if dash: g["dash"]=1
  if t: g.update(t=t,dx=dx,dy=dy)
  return g
def F(show=(),pts=("A","B","C","D","A′","B′","C′","D′")):
  g={"type":"plot","axes":False,"X":[-1.2,7.4],"Y":[-0.9,6.6],"eq":1,"w":560,"h":440,"segs":[],"pts":[]}
  g["segs"]+=[seg(a,b,"#8a91a5",2.5) for a,b in EDG]+[seg(a,b,"#8a91a5",2.5,1) for a,b in HID]
  if "base" in show: g["segs"]+=[seg("A","B","#c8242f",5,0,"u",0,26),seg("B","C","#2f55c8",5,0,"v",-20,-12),seg("A","A′","#16824f",5,0,"w",-18,0)]
  if "diag" in show: g["segs"].append(seg("A′","C′","#2f55c8",4,1))
  if "AE" in show: g["segs"].append(seg("A′","E","#f08a24",6))
  if "path" in show: g["segs"]+=[seg("F","C","#c8242f",5),seg("C","C′","#16824f",5),seg("C′","E","#2f55c8",5)]
  if "FE" in show: g["segs"].append(seg("F","E","#16824f",6))
  if "tri" in show: g["poly"]=[{"p":[list(P["A′"]),list(P["F"]),list(P["C′"])],"fill":"#f5b83d","op":.45}]; g["segs"]+=[seg("A′","F","#c8242f",3.5),seg("F","C′","#c8242f",3.5),seg("A′","C′","#c8242f",3.5)]
  for k in list(pts)+(["F"] if "F" not in pts else [])+(["E"] if "E" not in pts else []):
    g["pts"].append({"x":P[k][0],"y":P[k][1],"t":k,"r":5,"dx":LBL[k][0],"dy":LBL[k][1],"fs":21})
  return g
